import os
import hashlib
import subprocess
import pickle

# Vulnerable code patterns for security testing

def insecure_hash(password):
    # CWE-327: Use of a broken or risky cryptographic algorithm (MD5)
    return hashlib.md5(password.encode()).hexdigest()

def timing_attack_vuln(user_input, expected_value):
    # CWE-208: Observable Timing Discrepancy
    if user_input == expected_value:
        return True
    return False

def command_injection(user_cmd):
    # CWE-78: Improper Neutralization of Special Elements used in an OS Command 
    os.system("ls " + user_cmd)

def sql_injection(user_id):
    # CWE-89: Improper Neutralization of Special Elements used in an SQL Command
    query = "SELECT * FROM users WHERE id = " + user_id
    print(query)

def path_traversal(filename):
    # CWE-22: Improper Limitation of a Pathname to a Restricted Directory
    return open("/tmp/" + filename, "r")

def unsafe_deserialization(data):
    # CWE-502: Deserialization of Untrusted Data
    return pickle.loads(data)

def hardcoded_secret():
    # CWE-321: Use of Hard-coded Cryptographic Key
    SECRET_KEY = "my_hardcoded_secret"
    return SECRET_KEY

def weak_crypto_cipher():
    # CWE-327: Use of a broken or risky cryptographic algorithm (DES)
    import des  # This would be vulnerable

